SELECT record_id,lang,gene,variant,ori_variant,disease_id,result_type,gene_description,var_drug_desc,modified,update_by,unix_timestamp(str_to_date(update_date, '%Y-%m-%d %H:%i:%s')) as update_date,check_date
 from rp_unknown_var
WHERE gene = #{gene} and ori_variant = #{ori_variant} and disease_id= #{disease_id} and lang =#{lang}

select count(*) from rp_unknown_var_evw

	modified=1

		and update_date >= #{before_date}


		and update_date < #{after_date}

select record_id,lang, gene,variant,ori_variant,disease_id,disease_name_chinese,result_type,gene_description,var_drug_desc,modified,update_by,update_by,date_format(update_date,'%Y-%m-%d %H:%i:%s') as update_date ,date_format(check_date,'%Y-%m-%d %H:%i:%s') as check_date
from rp_unknown_var_evw

	modified=1

		and update_date >= #{before_date}


		and update_date < #{after_date}


limit #{pageNo},#{pageSize}

select record_id,lang, gene,variant,ori_variant,disease_id,disease_name_chinese,result_type,gene_description,var_drug_desc,modified,update_by,update_by,date_format(update_date,'%Y-%m-%d %H:%i:%s') as update_date ,date_format(check_date,'%Y-%m-%d %H:%i:%s') as check_date
from rp_unknown_var_evw

	modified=1

		and update_date >= #{before_date}


		and update_date < #{after_date}
